<?php $boards = is_array($boards ?? null) ? $boards : []; ?><div class="ui-page-index"><section class="page-header"><div><p class="eyebrow">Exams &amp; subjects</p><h1>Choose your examination</h1><p>Compare real content availability before you configure a session.</p></div></section><div class="ui-exam-grid exam-grid"><?php foreach ($boards as $board): ?><article class="ui-exam-card exam-card accent-<?= htmlspecialchars((string) (($board['visual']['accent'] ?? 'blue'))) ?>"><div class="exam-card-mark"><?php $icon=$board['visual']['icon']??'exam';$iconSize='lg';require dirname(__DIR__).'/components/icon.php'; ?></div><div class="exam-card-top"><span class="badge badge-info"><?= htmlspecialchars((string) ($board['code'] ?? 'Exam')) ?></span><span class="exam-status <?= ($board['study_status']??'')==='ready'?'status-ready':'status-soon' ?>"><?= ($board['study_status']??'')==='ready'?'Ready to study':'Coming soon' ?></span></div><h2><?= htmlspecialchars((string) ($board['name'] ?? '')) ?></h2><p><?= htmlspecialchars((string) ($board['description'] ?? '')) ?></p><div class="exam-counts"><span><b><?= (int)($board['available_subjects']??0) ?></b> available subjects</span><span><b><?= (int)($board['available_questions']??0) ?></b> questions</span></div><a class="button <?= ($board['study_status']??'')==='ready'?'button-green':'button-disabled' ?>" href="<?= ($board['study_status']??'')==='ready'?'/exams?exam='.urlencode((string)($board['code']??'')):'#' ?>"><?= ($board['study_status']??'')==='ready'?'Configure practice':'Repository in progress' ?></a></article><?php endforeach; ?></div></div>
